import sys
import os

def main():
    if len(sys.argv) != 4:
        print("ERROR: missing arguments", file=sys.stderr)
        sys.exit(1)

    cred_path = sys.argv[1]
    events_path = sys.argv[2]
    audit_path = sys.argv[3]

    try:
        with open(cred_path, 'r') as cred_file:
            credentials = [line.strip().split(',') for line in cred_file if line.strip()]
    except IOError as e:
        print(f"ERROR: {cred_path}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(events_path, 'r') as events_file:
            events = [line.strip() for line in events_file if line.strip()]
    except IOError as e:
        print(f"ERROR: {events_path}", file=sys.stderr)
        sys.exit(1)

    token = sys.stdin.readline().strip()
    if not token:
        print("ACCESS DENIED", file=sys.stderr)
        sys.exit(2)

    token_allowed_actions = None
    for line in credentials:
        if line[0] == token:
            token_allowed_actions = set(line[2].split('|'))
            break

    if not token_allowed_actions:
        print("ACCESS DENIED", file=sys.stderr)
        sys.exit(2)

    allowed_actions = token_allowed_actions

    try:
        with open(audit_path, 'a') as audit_file:
            for event in events:
                event_parts = event.split(',')
                if event_parts[1] == token and event_parts[2] in allowed_actions:
                    print(event)
                    audit_file.write(f"{event_parts[0]},{event_parts[1]},{event_parts[2]}\n")
    except IOError as e:
        print(f"ERROR: {audit_path}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

