import sys
import os

def main():
    if len(sys.argv) != 2:
        print("ERROR: missing credentials file path", file=sys.stderr)
        sys.exit(1)

    credentials_path = sys.argv[1]
    token = sys.stdin.readline().strip()

    try:
        with open(credentials_path, 'r') as creds_file:
            allowed_username = None
            allowed_action = None
            for line in creds_file:
                if line.startswith(token + ','):
                    parts = line.strip().split(',', 1)
                    if len(parts) >= 2:
                        allowed_username, allowed_action = parts[1].split(',', 1)
                        break
            else:
                print("ACCESS DENIED", file=sys.stderr)
                sys.exit(2)

            if allowed_username is None or allowed_action is None:
                print("ACCESS DENIED", file=sys.stderr)
                sys.exit(2)

            audit_log = open('audit.log', 'a', encoding='utf-8')
            for line in sys.stdin:
                parts = line.strip().split(',')
                if len(parts) >= 3 and parts[1] == allowed_username and parts[2] == allowed_action:
                    print(line.strip(), file=sys.stdout)
                    audit_log.write(line)
                    audit_log.write('\n')
            audit_log.close()
    except IOError as e:
        print(f"ERROR: {credentials_path}", file=sys.stderr)
        sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import os

def main():
    if len(sys.argv) != 2:
        print("ACCESS DENIED", file=sys.stderr)
        sys.exit(2)

    credentials_path = sys.argv[1]
    try:
        with open(credentials_path, 'r') as creds_file:
            credentials = [line.strip().split(',') for line in creds_file.readlines() if line.strip()]
    except IOError:
        print(f"ERROR: {credentials_path}", file=sys.stderr)
        sys.exit(1)

    token = sys.stdin.readline().strip()
    allowed_username = None
    allowed_action = None

    for cred in credentials:
        if cred[0] == token:
            allowed_username = cred[1]
            allowed_action = cred[2]
            break

    if not allowed_username:
        print("ACCESS DENIED", file=sys.stderr)
        sys.exit(2)

    audit_log = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        timestamp, username, action = line.split(',')
        if username == allowed_username and action == allowed_action:
            print(line)
            audit_log.append(line)

    try:
        with open('audit.log', 'a') as log_file:
            log_file.writelines(audit_log)
    except IOError:
        print("ERROR: audit.log", file=sys.stderr)
        sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()
